CREATE OR REPLACE FUNCTION authz.guard_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' OR TG_TABLE_NAME='identity_consumptions' THEN
 RAISE EXCEPTION USING ERRCODE='P1005',MESSAGE='Integrity.Immutable'; END IF;
 IF TG_TABLE_NAME IN('enterprise_user_accounts','memberships') THEN
  IF OLD.status IS DISTINCT FROM NEW.status AND NOT (OLD.status='Active' AND NEW.status='Revoked')
  THEN RAISE EXCEPTION USING ERRCODE='P1006',MESSAGE='Integrity.TransitionDenied'; END IF;
 END IF;
 IF TG_TABLE_NAME='memberships' THEN
  IF OLD.role IS DISTINCT FROM NEW.role
  THEN RAISE EXCEPTION USING ERRCODE='P1006',MESSAGE='Integrity.RoleImmutable'; END IF;
 END IF;
 IF (to_jsonb(OLD)-ARRAY['status','version','name','role']) IS DISTINCT FROM
    (to_jsonb(NEW)-ARRAY['status','version','name','role'])
 THEN RAISE EXCEPTION USING ERRCODE='P1005',MESSAGE='Integrity.Immutable'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION authz.guard_invitation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE predecessor record;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'Pending' OR NEW.accepted_account_id IS NOT NULL OR NEW.successor_id IS NOT NULL OR NEW.version<>1
  THEN RAISE EXCEPTION USING ERRCODE='P1010',MESSAGE='Invitation.InvalidInsert'; END IF;
  IF current_user='exec_tenant' THEN
   IF NOT authz.own_tenant_allowed(true) OR NEW.organization_id IS DISTINCT FROM authz.ctx('app.organization_id')
    OR NEW.recipient_identity_id IS DISTINCT FROM authz.ctx('app.recipient_id')
    OR NOT EXISTS(SELECT FROM tenancy.memberships WHERE id=NEW.issuer_membership_id
      AND account_id=authz.ctx('app.account_id') AND organization_id=NEW.organization_id AND status='Active' AND role IN('Owner','Admin'))
   THEN RAISE EXCEPTION USING ERRCODE='P1011',MESSAGE='Invitation.IssuerDenied'; END IF;
   IF EXISTS(SELECT FROM identity.identity_consumptions WHERE identity_id=NEW.recipient_identity_id)
    OR NOT EXISTS(SELECT FROM identity.identities WHERE id=NEW.recipient_identity_id AND status='Active')
   THEN RAISE EXCEPTION USING ERRCODE='P1012',MESSAGE='Invitation.RecipientIneligible'; END IF;
   -- No initial-issuance SQL port exists. This is not a table-wide NOT NULL
   -- requirement: initial privileged fixtures retain predecessor NULL.
   IF NEW.predecessor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='P1013',MESSAGE='Invitation.InitialIssueUnavailable'; END IF;
  END IF;
  IF NEW.predecessor_id IS NOT NULL THEN
   SELECT id,organization_id,recipient_identity_id,status,successor_id INTO predecessor FROM tenancy.invitations WHERE id=NEW.predecessor_id;
   IF NOT FOUND OR predecessor.organization_id<>NEW.organization_id OR predecessor.recipient_identity_id<>NEW.recipient_identity_id
    OR predecessor.status<>'Replaced' OR predecessor.successor_id IS NOT NULL OR NEW.predecessor_id=NEW.id
   THEN RAISE EXCEPTION USING ERRCODE='P1014',MESSAGE='Invitation.InvalidChain'; END IF;
  END IF;
 ELSE
  IF (to_jsonb(OLD)-ARRAY['status','version','accepted_account_id','successor_id']) IS DISTINCT FROM
     (to_jsonb(NEW)-ARRAY['status','version','accepted_account_id','successor_id'])
  THEN RAISE EXCEPTION USING ERRCODE='P1014',MESSAGE='Invitation.Immutable'; END IF;
  IF OLD.status IS DISTINCT FROM NEW.status AND NOT
    ((OLD.status='Pending' AND NEW.status IN('Accepted','Expired','Cancelled','Replaced')) OR (OLD.status='Expired' AND NEW.status='Replaced'))
  THEN RAISE EXCEPTION USING ERRCODE='P1014',MESSAGE='Invitation.InvalidTransition'; END IF;
  IF NEW.accepted_account_id IS DISTINCT FROM OLD.accepted_account_id THEN
   IF OLD.status<>'Pending' OR NEW.status<>'Accepted' OR OLD.accepted_account_id IS NOT NULL
    OR NOT EXISTS(SELECT FROM identity.enterprise_user_accounts WHERE id=NEW.accepted_account_id AND identity_id=NEW.recipient_identity_id AND organization_id=NEW.organization_id AND status='Active')
   THEN RAISE EXCEPTION USING ERRCODE='P1014',MESSAGE='Invitation.InvalidAcceptance'; END IF;
  END IF;
  IF NEW.successor_id IS DISTINCT FROM OLD.successor_id THEN
   IF OLD.successor_id IS NOT NULL OR OLD.status<>'Replaced' OR NEW.status<>'Replaced'
    OR NOT EXISTS(SELECT FROM tenancy.invitations WHERE id=NEW.successor_id AND predecessor_id=NEW.id AND organization_id=NEW.organization_id AND recipient_identity_id=NEW.recipient_identity_id AND status='Pending')
   THEN RAISE EXCEPTION USING ERRCODE='P1014',MESSAGE='Invitation.InvalidChain'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION authz.validate_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE org uuid; obj record; ostate text;
BEGIN
 IF TG_TABLE_NAME='organizations' THEN org:=NEW.id; ELSE org:=NEW.organization_id; END IF;
 IF org IS NULL OR org IS DISTINCT FROM authz.ctx('app.integrity_org')
 OR current_setting('app.integrity_tx',true) IS DISTINCT FROM pg_current_xact_id()::text
 OR nullif(current_setting('app.operation_id',true),'') IS NULL
 THEN RAISE EXCEPTION USING ERRCODE='P1001',MESSAGE='Integrity.ContextInvalid'; END IF;
 SELECT status INTO ostate FROM tenancy.organizations WHERE id=org;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P1002',MESSAGE='Integrity.AnchorMissing'; END IF;
 -- Deliberately no row/advisory locks: writers already hold the org lock.
 FOR obj IN SELECT a.id,a.status FROM identity.enterprise_user_accounts a WHERE a.organization_id=org LOOP
  IF obj.status='Active' AND (SELECT count(*) FROM tenancy.memberships m WHERE m.organization_id=org AND m.account_id=obj.id AND m.status='Active')<>1
  THEN RAISE EXCEPTION USING ERRCODE='P1003',MESSAGE='Integrity.AccountMembership'; END IF;
  IF obj.status<>'Active' AND EXISTS(SELECT FROM tenancy.memberships m WHERE m.organization_id=org AND m.account_id=obj.id AND m.status='Active')
  THEN RAISE EXCEPTION USING ERRCODE='P1003',MESSAGE='Integrity.AccountMembership'; END IF;
 END LOOP;
 IF EXISTS(SELECT FROM tenancy.memberships m LEFT JOIN identity.enterprise_user_accounts a ON a.id=m.account_id AND a.organization_id=m.organization_id
 WHERE m.organization_id=org AND m.status='Active' AND (a.id IS NULL OR a.status<>'Active'))
 THEN RAISE EXCEPTION USING ERRCODE='P1003',MESSAGE='Integrity.AccountMembership'; END IF;
 IF ostate='Active' AND NOT EXISTS(SELECT FROM tenancy.memberships m
 JOIN identity.enterprise_user_accounts a ON a.id=m.account_id AND a.organization_id=m.organization_id
 WHERE m.organization_id=org AND m.role='Owner' AND m.status='Active' AND a.status='Active')
 THEN RAISE EXCEPTION USING ERRCODE='P1004',MESSAGE='Integrity.OwnerMissing'; END IF;
 IF TG_TABLE_NAME='memberships' THEN
  IF OLD.role='Owner' AND OLD.status='Active' AND NEW.status='Revoked'
  THEN RAISE EXCEPTION USING ERRCODE='P1007',MESSAGE='Integrity.OwnerRevocationDenied'; END IF;
  IF NOT EXISTS(SELECT FROM identity.enterprise_user_accounts WHERE id=NEW.account_id AND organization_id=org)
  THEN RAISE EXCEPTION USING ERRCODE='P1002',MESSAGE='Integrity.AnchorMissing'; END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION authz.validate_invitation_chain()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE item record;
BEGIN
 IF NEW.organization_id IS DISTINCT FROM authz.ctx('app.integrity_org')
 OR current_setting('app.integrity_tx',true) IS DISTINCT FROM pg_current_xact_id()::text
 THEN RAISE EXCEPTION USING ERRCODE='P1014',MESSAGE='Invitation.ChainContextInvalid'; END IF;
 SELECT id,organization_id,recipient_identity_id,status,predecessor_id,successor_id INTO item FROM tenancy.invitations WHERE id=NEW.id;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P1014',MESSAGE='Invitation.ChainAnchorMissing'; END IF;
 IF (item.status='Replaced' AND item.successor_id IS NULL)
 OR (item.predecessor_id IS NOT NULL AND NOT EXISTS(SELECT FROM tenancy.invitations WHERE id=item.predecessor_id AND successor_id=item.id AND status='Replaced' AND organization_id=item.organization_id AND recipient_identity_id=item.recipient_identity_id))
 THEN RAISE EXCEPTION USING ERRCODE='P1014',MESSAGE='Invitation.IncompleteChain'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION operation.accept_invitation(inv uuid, secret text, expected_version bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE item record; aid uuid:=gen_random_uuid(); actor uuid:=authz.ctx('app.identity_id');
BEGIN
 IF session_user<>'core_identity' OR actor IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 SELECT id,organization_id,recipient_identity_id,status,expires_at,version,accepted_account_id INTO item FROM tenancy.invitations WHERE id=inv AND recipient_identity_id=actor AND secret_hash=sha256(convert_to(secret,'UTF8'));
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P2003',MESSAGE='Invitation.Unavailable'; END IF;
 PERFORM id FROM identity.identities WHERE id=actor AND status='Active' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 PERFORM set_config('app.organization_id',item.organization_id::text,true);
 PERFORM id FROM tenancy.organizations WHERE id=item.organization_id AND status='Active' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 -- Revalidate in a new statement after the identity/org waits.
 SELECT id,organization_id,recipient_identity_id,status,expires_at,version,accepted_account_id INTO item FROM tenancy.invitations WHERE id=inv AND recipient_identity_id=actor
 AND secret_hash=sha256(convert_to(secret,'UTF8'));
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P2003',MESSAGE='Invitation.Unavailable'; END IF;
 IF item.status='Accepted' THEN
  SELECT id INTO aid FROM identity.enterprise_user_accounts WHERE id=item.accepted_account_id AND status='Active';
  IF aid IS NULL OR NOT EXISTS(SELECT FROM tenancy.memberships WHERE account_id=aid AND status='Active')
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Unavailable'; END IF;
  RETURN aid;
 END IF;
 IF EXISTS(SELECT FROM identity.identity_consumptions WHERE identity_id=actor) THEN
 RAISE EXCEPTION USING ERRCODE='P2002',MESSAGE='Account.Ineligible'; END IF;
 INSERT INTO tenancy.invitation_slots(organization_id,recipient_identity_id) VALUES(item.organization_id,actor) ON CONFLICT DO NOTHING;
 PERFORM version FROM tenancy.invitation_slots WHERE organization_id=item.organization_id AND recipient_identity_id=actor FOR UPDATE;
 SELECT id,organization_id,recipient_identity_id,status,expires_at,version,accepted_account_id INTO item FROM tenancy.invitations WHERE id=inv FOR UPDATE;
 IF item.status<>'Pending' THEN RAISE EXCEPTION USING ERRCODE='P2004',MESSAGE='Invitation.StateConflict'; END IF;
 IF item.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='P2005',MESSAGE='Invitation.Expired'; END IF;
 IF expected_version IS NULL THEN RAISE EXCEPTION USING ERRCODE='P2006',MESSAGE='Version.Required'; END IF;
 IF item.version<>expected_version THEN RAISE EXCEPTION USING ERRCODE='P2007',MESSAGE='Version.Stale'; END IF;
 PERFORM set_config('app.integrity_org',item.organization_id::text,true);
 PERFORM set_config('app.integrity_tx',pg_current_xact_id()::text,true);
 PERFORM set_config('app.operation_id',gen_random_uuid()::text,true);
 INSERT INTO identity.identity_consumptions(identity_id,organization_id,account_id) VALUES(actor,item.organization_id,aid);
 INSERT INTO identity.enterprise_user_accounts(id,identity_id,organization_id,status) VALUES(aid,actor,item.organization_id,'Active');
 INSERT INTO tenancy.memberships(id,organization_id,account_id,role,status) VALUES(gen_random_uuid(),item.organization_id,aid,'Member','Active');
 UPDATE tenancy.invitations SET status='Accepted',accepted_account_id=aid,version=version+1 WHERE id=inv;
 INSERT INTO audit.events(organization_id,actor_id,action,operation_id) VALUES(item.organization_id,actor,'Accept',authz.ctx('app.operation_id'));
 RETURN aid;
END $function$

CREATE OR REPLACE FUNCTION operation.bootstrap(owner_identity uuid, org uuid, org_name text, request_key text, owner_reference text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE existing record; aid uuid:=gen_random_uuid(); mid uuid:=gen_random_uuid(); actor uuid:=authz.ctx('app.identity_id');
BEGIN
 IF session_user <> 'core_platform' OR actor IS NULL OR request_key IS NULL OR length(request_key)=0
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 PERFORM set_config('app.recipient_id',owner_identity::text,true);
 -- OIDC/MFA stays at the Application boundary; C02 hash proof is rechecked below.
 INSERT INTO operation.idempotency_records(actor_id,scope_key,operation,key,request_hash,result_id)
 VALUES(actor,'Platform','bootstrap',request_key,owner_identity::text||':'||org::text||':'||org_name,org)
 ON CONFLICT(actor_id,scope_key,operation,key) DO NOTHING;
 SELECT actor_id,scope_key,operation,key,request_hash,result_id INTO existing FROM operation.idempotency_records
 WHERE actor_id=actor AND scope_key='Platform' AND operation='bootstrap' AND key=request_key;
 IF existing.request_hash <> owner_identity::text||':'||org::text||':'||org_name
 THEN RAISE EXCEPTION USING ERRCODE='P2001',MESSAGE='Idempotency.PayloadMismatch'; END IF;
 -- A previous result exists only if the organization was committed.
 PERFORM set_config('app.integrity_org',org::text,true);
 IF EXISTS(SELECT FROM tenancy.organizations WHERE id=existing.result_id) THEN RETURN existing.result_id; END IF;
 PERFORM id FROM identity.identities WHERE id=ANY(ARRAY[actor,owner_identity]) ORDER BY id FOR UPDATE;
 IF NOT EXISTS(SELECT FROM identity.recipient_references WHERE identity_id=owner_identity
 AND secret_hash=sha256(convert_to(owner_reference,'UTF8')) AND expires_at>clock_timestamp())
 THEN RAISE EXCEPTION USING ERRCODE='P2003',MESSAGE='Recipient.Unavailable'; END IF;
 IF NOT EXISTS(SELECT FROM identity.identities WHERE id=owner_identity AND status='Active')
 OR EXISTS(SELECT FROM identity.identity_consumptions WHERE identity_id=owner_identity)
 THEN RAISE EXCEPTION USING ERRCODE='P2002',MESSAGE='Account.Ineligible'; END IF;
 PERFORM set_config('app.integrity_tx',pg_current_xact_id()::text,true);
 PERFORM set_config('app.operation_id',gen_random_uuid()::text,true);
 INSERT INTO tenancy.organizations(id,name,status) VALUES(org,org_name,'Active');
 INSERT INTO identity.identity_consumptions(identity_id,organization_id,account_id) VALUES(owner_identity,org,aid);
 INSERT INTO identity.enterprise_user_accounts(id,identity_id,organization_id,status) VALUES(aid,owner_identity,org,'Active');
 INSERT INTO tenancy.memberships(id,organization_id,account_id,role,status) VALUES(mid,org,aid,'Owner','Active');
 INSERT INTO audit.events(organization_id,actor_id,action,operation_id) VALUES(org,actor,'Bootstrap',authz.ctx('app.operation_id'));
 RETURN org;
END $function$

CREATE OR REPLACE FUNCTION operation.replace_invitation(inv uuid, expected_version bigint, request_key text, new_secret text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE item record; receipt record;
 actor uuid:=authz.ctx('app.identity_id'); org uuid:=authz.ctx('app.organization_id'); next_id uuid:=gen_random_uuid(); issuer_id uuid;
BEGIN
 IF session_user<>'core_tenant' OR NOT authz.own_tenant_allowed(true) OR request_key IS NULL OR length(request_key)=0
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 IF expected_version IS NULL THEN RAISE EXCEPTION USING ERRCODE='P2006',MESSAGE='Version.Required'; END IF;
 IF new_secret IS NULL OR length(new_secret)<64 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid generated secret'; END IF;
 INSERT INTO operation.idempotency_records(actor_id,scope_key,operation,key,request_hash,result_id)
 VALUES(actor,org::text,'replace',request_key,inv::text||':'||expected_version::text,next_id)
 ON CONFLICT(actor_id,scope_key,operation,key) DO NOTHING;
 SELECT actor_id,scope_key,operation,key,request_hash,result_id INTO receipt FROM operation.idempotency_records
 WHERE actor_id=actor AND scope_key=org::text AND operation='replace' AND key=request_key;
 IF receipt.request_hash<>inv::text||':'||expected_version::text
 THEN RAISE EXCEPTION USING ERRCODE='P2001',MESSAGE='Idempotency.PayloadMismatch'; END IF;
 IF EXISTS(SELECT FROM tenancy.invitations WHERE id=receipt.result_id) THEN RETURN receipt.result_id; END IF;
 SELECT id,organization_id,recipient_identity_id,issuer_membership_id,status,expires_at,version INTO item FROM tenancy.invitations WHERE id=inv AND organization_id=org;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P2003',MESSAGE='Invitation.Unavailable'; END IF;
 PERFORM set_config('app.recipient_id',item.recipient_identity_id::text,true);
 PERFORM id FROM identity.identities WHERE id=ANY(ARRAY[actor,item.recipient_identity_id]) ORDER BY id FOR UPDATE;
 PERFORM id FROM tenancy.organizations WHERE id=org FOR UPDATE;
 PERFORM id FROM identity.enterprise_user_accounts WHERE id=authz.ctx('app.account_id') FOR UPDATE;
 PERFORM id FROM tenancy.memberships WHERE account_id=authz.ctx('app.account_id') ORDER BY id FOR UPDATE;
 IF NOT authz.own_tenant_allowed(true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 SELECT id INTO issuer_id FROM tenancy.memberships WHERE account_id=authz.ctx('app.account_id') AND organization_id=org AND status='Active' AND role IN('Owner','Admin');
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 IF NOT EXISTS(SELECT FROM identity.identities WHERE id=item.recipient_identity_id AND status='Active')
 OR EXISTS(SELECT FROM identity.identity_consumptions WHERE identity_id=item.recipient_identity_id)
 THEN RAISE EXCEPTION USING ERRCODE='P2002',MESSAGE='Account.Ineligible'; END IF;
 INSERT INTO tenancy.invitation_slots(organization_id,recipient_identity_id) VALUES(org,item.recipient_identity_id) ON CONFLICT DO NOTHING;
 PERFORM version FROM tenancy.invitation_slots WHERE organization_id=org AND recipient_identity_id=item.recipient_identity_id FOR UPDATE;
 SELECT id,organization_id,recipient_identity_id,issuer_membership_id,status,expires_at,version INTO item FROM tenancy.invitations WHERE id=inv FOR UPDATE;
 IF item.version<>expected_version THEN RAISE EXCEPTION USING ERRCODE='P2007',MESSAGE='Version.Stale'; END IF;
 IF item.status NOT IN('Pending','Expired') THEN RAISE EXCEPTION USING ERRCODE='P2004',MESSAGE='Invitation.StateConflict'; END IF;
 IF item.status='Pending' AND item.expires_at<=clock_timestamp() THEN
  UPDATE tenancy.invitations SET status='Expired',version=version+1 WHERE id=inv;
  INSERT INTO audit.events(organization_id,actor_id,action,operation_id) VALUES(org,actor,'ExpireInvitation',gen_random_uuid());
 END IF;
 PERFORM set_config('app.integrity_org',org::text,true);
 PERFORM set_config('app.integrity_tx',pg_current_xact_id()::text,true);
 PERFORM set_config('app.operation_id',gen_random_uuid()::text,true);
 -- Clear the partial Pending index before inserting successor; no temporary broken FK.
 UPDATE tenancy.invitations SET status='Replaced',version=version+1 WHERE id=inv;
 INSERT INTO tenancy.invitations(id,organization_id,recipient_identity_id,issuer_membership_id,secret_hash,status,expires_at,predecessor_id)
 VALUES(next_id,org,item.recipient_identity_id,issuer_id,sha256(convert_to(new_secret,'UTF8')),'Pending',clock_timestamp()+interval '24 hours',inv);
 UPDATE tenancy.invitations SET successor_id=next_id,version=version+1 WHERE id=inv;
 INSERT INTO audit.events(organization_id,actor_id,action,operation_id) VALUES(org,actor,'ReplaceInvitation',gen_random_uuid());
 RETURN next_id;
END $function$

CREATE OR REPLACE FUNCTION operation.revoke_membership(target uuid, expected_version bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor uuid:=authz.ctx('app.identity_id'); org uuid:=authz.ctx('app.organization_id');
 target_account uuid; target_identity uuid; target_role text; target_version bigint; actor_role text;
BEGIN
 IF session_user<>'core_tenant' OR NOT authz.own_tenant_allowed(true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 SELECT account_id INTO target_account FROM tenancy.memberships WHERE id=target AND organization_id=org;
 SELECT identity_id INTO target_identity FROM identity.enterprise_user_accounts WHERE id=target_account;
 IF target_identity IS NULL OR target_identity=actor THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 PERFORM set_config('app.recipient_id',target_identity::text,true);
 PERFORM id FROM identity.identities WHERE id=ANY(ARRAY[actor,target_identity]) ORDER BY id FOR UPDATE;
 PERFORM id FROM tenancy.organizations WHERE id=org FOR UPDATE;
 PERFORM id FROM identity.enterprise_user_accounts WHERE id=ANY(ARRAY[authz.ctx('app.account_id'),target_account]) ORDER BY id FOR UPDATE;
 PERFORM id FROM tenancy.memberships WHERE account_id=ANY(ARRAY[authz.ctx('app.account_id'),target_account]) ORDER BY id FOR UPDATE;
 IF NOT authz.own_tenant_allowed(true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 SELECT role INTO actor_role FROM tenancy.memberships WHERE account_id=authz.ctx('app.account_id') AND status='Active';
 SELECT role,version INTO target_role,target_version FROM tenancy.memberships WHERE id=target AND status='Active';
 IF target_role IS NULL OR target_role='Owner' OR (actor_role='Admin' AND target_role<>'Member')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 IF expected_version IS NULL THEN RAISE EXCEPTION USING ERRCODE='P2006',MESSAGE='Version.Required'; END IF;
 IF target_version<>expected_version THEN RAISE EXCEPTION USING ERRCODE='P2007',MESSAGE='Version.Stale'; END IF;
 PERFORM set_config('app.integrity_org',org::text,true);
 PERFORM set_config('app.integrity_tx',pg_current_xact_id()::text,true);
 PERFORM set_config('app.operation_id',gen_random_uuid()::text,true);
 UPDATE identity.enterprise_user_accounts SET status='Revoked',version=version+1 WHERE id=target_account;
 UPDATE tenancy.memberships SET status='Revoked',version=version+1 WHERE id=target;
 INSERT INTO audit.events(organization_id,actor_id,action,operation_id) VALUES(org,actor,'Revoke',authz.ctx('app.operation_id'));
END $function$

CREATE OR REPLACE FUNCTION operation.update_demo(target uuid, expected_version bigint, new_title text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE ver bigint; actor uuid:=authz.ctx('app.identity_id'); org uuid:=authz.ctx('app.organization_id');
BEGIN
 IF session_user<>'core_tenant' OR NOT authz.own_tenant_allowed(true)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 PERFORM id FROM identity.identities WHERE id=actor FOR SHARE;
 PERFORM id FROM tenancy.organizations WHERE id=org FOR UPDATE;
 PERFORM id FROM identity.enterprise_user_accounts WHERE id=authz.ctx('app.account_id') FOR UPDATE;
 PERFORM id FROM tenancy.memberships WHERE account_id=authz.ctx('app.account_id') ORDER BY id FOR UPDATE;
 IF NOT authz.own_tenant_allowed(true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Access.Denied'; END IF;
 SELECT version INTO ver FROM sandbox.demo_records WHERE id=target AND organization_id=org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P2003',MESSAGE='Resource.Unavailable'; END IF;
 IF expected_version IS NULL THEN RAISE EXCEPTION USING ERRCODE='P2006',MESSAGE='Version.Required'; END IF;
 IF ver<>expected_version THEN RAISE EXCEPTION USING ERRCODE='P2007',MESSAGE='Version.Stale'; END IF;
 UPDATE sandbox.demo_records SET title=new_title,version=version+1 WHERE id=target RETURNING version INTO ver;
 INSERT INTO audit.events(organization_id,actor_id,action,operation_id) VALUES(org,actor,'UpdateDemo',gen_random_uuid());
 RETURN ver;
END $function$
